def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def blob(b): return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
def read(p): return json.loads(Path(p).read_text())
def write(p, obj):
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(obj,indent=2,ensure_ascii=False,sort_keys=True)+'\n')
def bind(p,repo):
    b=p.read_bytes()
    return dict(path=p.relative_to(repo).as_posix(),bytes=len(b),sha256=hashlib.sha256(b).hexdigest(),git_blob_sha1=blob(b))
def normalized_record(row, old, repo):
    p=old/row['path']; b=p.read_bytes()
    expected=row.get('transport',row)
    assert len(b)==expected['bytes'] and hashlib.sha256(b).hexdigest()==expected['sha256'], str(p)
    assert blob(b)==expected['git_blob_sha1'],str(p)
    result=dict(record=copy.deepcopy(row),verified_file=bind(p,repo))
    if 'transport' in row:
        native=gzip.decompress(b);expected=row['original']
        assert len(native)==expected['bytes'] and hashlib.sha256(native).hexdigest()==expected['sha256'] and blob(native)==expected['git_blob_sha1'],str(p)
        result['exact_decompressed_original_verified']=True
    return result
def tex_escape(s):
    return ''.join({'&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}'}.get(c,c) for c in s)
def tex_plain(s):
    # This is for readable Markdown copies; the exact complete author LaTeX is
    # preserved in both source and the machine map.
    s=re.sub(r'~?\\ref\{([^}]+)\}',r' (source label: \1)',s)
    return s.replace('\\%','%').replace('\\&','&').replace('$','')

